<!doctype html><html lang="en" data-theme="light"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sign in — Festiva</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet"><style>:root{--card:#fff;--ink:#25233a}html[data-theme=dark]{--card:#211c2c;--ink:#f2edf7}body{min-height:100vh;background:linear-gradient(135deg,#30175a,#d64e70);display:grid;place-items:center}.login-card{width:min(440px,92vw);background:var(--card);color:var(--ink);border:0;border-radius:24px;box-shadow:0 20px 60px #17072980}.mark{width:52px;height:52px;border-radius:16px;background:#6b2e92;color:white;display:grid;place-items:center;font-size:25px}.form-control{background:var(--card);color:var(--ink)}</style></head><body><section class="card login-card p-4 p-md-5 position-relative"><button id="theme-toggle" class="btn btn-sm btn-outline-secondary position-absolute top-0 end-0 m-3"><i class="bi bi-moon-stars"></i></button><div class="mark mb-4">✦</div><p class="text-uppercase text-muted small mb-1">Welcome to Festiva</p><h1 class="h2 fw-bold mb-2">Plan something memorable.</h1><p class="text-muted mb-4">Sign in to manage your events, schedules, and budgets.</p>@if($errors->any())<div class="alert alert-danger">{{$errors->first()}}</div>@endif<form method="post" action="{{ route('login.store') }}">@csrf<div class="mb-3"><label class="form-label">Email address</label><input class="form-control form-control-lg" type="email" name="email" value="{{old('email')}}" required autofocus></div><div class="mb-3"><label class="form-label">Password</label><input class="form-control form-control-lg" type="password" name="password" required></div><div class="form-check mb-4"><input class="form-check-input" type="checkbox" name="remember" value="1" id="remember"><label class="form-check-label" for="remember">Keep me signed in</label></div><button class="btn btn-primary btn-lg w-100">Sign in</button></form><p class="text-muted small text-center mt-4 mb-0">Demo: admin@festiva.test / password</p></section><script>const k='festiva-theme',h=document.documentElement,b=document.getElementById('theme-toggle');function t(v){h.dataset.theme=v;b.innerHTML=v==='dark'?'<i class="bi bi-sun"></i>':'<i class="bi bi-moon-stars"></i>'}t(localStorage.getItem(k)||'light');b.onclick=()=>{let v=h.dataset.theme==='dark'?'light':'dark';localStorage.setItem(k,v);t(v)}</script></body></html>
